import{_ as o,H as t,f as r,i as a}from"./chunks/framework.CBmkDW73.js";const f=JSON.parse('{"title":"review","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/review.md","filePath":"ja/skills/review.md"}'),i={name:"ja/skills/review.md"};function l(n,e,s,d,c,_){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="review" tabindex="-1">review <a class="header-anchor" href="#review" aria-label="Permalink to &quot;review&quot;">​</a></h1><p><code>review</code> スキルは、マージ前、サブエージェント作業完了後、または仕様書・計画書のレビュー時に実行します。マルチモジュール作業では各モジュール所属リポジトリの diff を先にレビューし、その後ワークスペース全体の変更セットとして評価します。</p><h2 id="_8項目チェックリスト" tabindex="-1">8項目チェックリスト <a class="header-anchor" href="#_8項目チェックリスト" aria-label="Permalink to &quot;8項目チェックリスト&quot;">​</a></h2><p>優先順位に従って確認します：</p><ol><li><strong>仕様一致</strong>：diff がステージング仕様と計画どおりに実装されており、無記録のドリフトがないこと。</li><li><strong>標準準拠</strong>：lint/format/typecheck が通過し、コードが <code>convention:</code> に適合していること（<a href="./quality.html">品質標準</a>）。</li><li><strong>テスト</strong>：新しい挙動とエッジケースがテストで保護され全件パスすること。</li><li><strong>ドキュメント網羅性とリビングドキュメント</strong>：<code>contract</code> が公開面全体を覆い、設定・エラーモードが文書化され、<code>README.md</code> のコマンドが実行可能であり、リビングドキュメントが非時系列かつ適切にモジュール分割されていること。</li><li><strong>境界条件</strong>：null、空値、大容量データ、並行実行、不正入力、Unicode、タイムゾーンの扱い。</li><li><strong>セキュリティ</strong>：入力検証、シークレット保護、認可境界、インジェクション、パストラバーサル。</li><li><strong>スコープ</strong>：無関係な変更は差し戻し、必要以上に複雑な実装（&gt;2x）は指摘して簡素化すること。</li><li><strong>統合検証（マルチモジュール）</strong>：依存順、互換性、失敗伝播、Coordinator 統合受入が参加モジュール全体をカバーしていること。</li></ol><h2 id="出力フォーマット" tabindex="-1">出力フォーマット <a class="header-anchor" href="#出力フォーマット" aria-label="Permalink to &quot;出力フォーマット&quot;">​</a></h2><p>指摘事項は <code>BLOCK</code>（マージ前修正必須）、<code>FIX</code>（修正または理由付き保留）、<code>NIT</code>（任意改善）の形式で報告します。</p>',7)])])}const g=o(i,[["render",l]]);export{f as __pageData,g as default};
